// Audits only PSDs generated by daily-use-smoke, preserving other Photoshop documents.
import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {execFile} from 'node:child_process';import {promisify} from 'node:util';
const out=path.resolve('test-results/daily-use'),jobs=JSON.parse(await readFile(path.join(out,'resultado.json'),'utf8'));
if(jobs.length!==3||jobs.some(j=>j.native?.state!=='complete'))throw new Error('Conclua os três testes nativos antes da auditoria.');
const report=path.join(out,'auditoria-psds.txt'),script=path.join(out,'auditar-psds.jsx');
const jsx=`#target photoshop
(function(){var jobs=${JSON.stringify(jobs.map(j=>({file:path.join(j.native.output,'cartelas.psd').replaceAll('\\','/'),cards:j.manifest.cards})))},report=${JSON.stringify(report.replaceAll('\\','/'))},count=app.documents.length,original=count?app.activeDocument:null,oldUnits=app.preferences.rulerUnits,oldDialogs=app.displayDialogs,doc=null,groups=0,photos=0,texts=0,result='';
try{app.preferences.rulerUnits=Units.PIXELS;app.displayDialogs=DialogModes.NO;
for(var j=0;j<jobs.length;j++){doc=app.open(new File(jobs[j].file));if(doc.width.as('px')!==1280||doc.height.as('px')!==720||doc.layers.length!==jobs[j].cards.length)throw new Error('Dimensões ou grupos divergentes');
for(var c=0;c<jobs[j].cards.length;c++){var card=jobs[j].cards[c],group=doc.layers[c];if(group.typename!=='LayerSet'||group.name!==card.name||group.visible!==(c===0)||group.layers.length!==card.layers.length)throw new Error('Grupo divergente');groups++;
for(var i=0;i<card.layers.length;i++){var item=card.layers[i],layer=group.artLayers.getByName(item.name);if(item.type==='text'){if(layer.kind!==LayerKind.TEXT||layer.textItem.contents!==item.lines.join(String.fromCharCode(13)))throw new Error('Texto divergente');texts++;}if(item.type==='photo'){if(layer.kind!==LayerKind.SMARTOBJECT)throw new Error('Foto sem objeto inteligente');doc.activeLayer=layer;var ref=new ActionReference();ref.putEnumerated(stringIDToTypeID('layer'),stringIDToTypeID('ordinal'),stringIDToTypeID('targetEnum'));var data=executeActionGet(ref);if(!data.getBoolean(stringIDToTypeID('hasUserMask'))||data.getBoolean(stringIDToTypeID('userMaskLinked')))throw new Error('Máscara da foto divergente');photos++;}}
}doc.close(SaveOptions.DONOTSAVECHANGES);doc=null;}
if(app.documents.length!==count)throw new Error('Documentos anteriores divergentes');result='OK|documents=3|groups='+groups+'|smartPhotos='+photos+'|nativeTexts='+texts+'|userDocumentsPreserved=true';
}catch(e){result='ERROR|'+e.message;}finally{if(doc){try{doc.close(SaveOptions.DONOTSAVECHANGES);}catch(e){}}app.preferences.rulerUnits=oldUnits;app.displayDialogs=oldDialogs;if(original){try{app.activeDocument=original;}catch(e){}}}var file=new File(report);file.encoding='UTF-8';file.open('w');file.write(result);file.close();return result;}());`;
await writeFile(script,jsx,'utf8');await promisify(execFile)('cscript.exe',['//nologo',path.resolve('scripts/photoshop-run.vbs'),script],{windowsHide:true,timeout:120000,maxBuffer:32768});const text=(await readFile(report,'utf8')).replace(/^\uFEFF/,'');if(!text.startsWith('OK|'))throw new Error(text);console.log(text);
